import { describe, expect, it } from 'vitest'
import { applyCommand, money, type VendorWorkspace, type NewBatch } from './model'
const now=new Date('2026-10-01T12:00:00Z')
const seed:VendorWorkspace={stalls:[{id:'s',market_id:'m',name:'Demo stall',category:'Rice',specialty:'Rice',price_sen:500,halal:'declared',open:true,lot:'A1',opens:'17:00',closes:'22:00',latitude:3,longitude:101,photo:null}],foods:[{id:'f',stall_id:'s',name:'Rice',price_sen:500,ingredients:['rice'],photo:null}],batches:[],events:[],requests:{}}
const data:NewBatch={food_item_id:'f',prepared_at:'2026-10-01T11:00:00Z',quantity:10,handling:{storage:'ambient',note:''},photo:'original-photo'}
const create=(s=seed,key='r',id='b',d=data)=>applyCommand(s,{kind:'batch',data:d},key,now,id).workspace
describe('independent auditable batches',()=>{
 it('numbers separate batches without rewriting old preparation or photos',()=>{const first=create();const second=create(first,'r2','b2',{...data,photo:'second-photo'});expect(second.batches.map(b=>b.batch_number)).toEqual([1,2]);expect(second.batches[0]).toEqual(first.batches[0]);expect(seed.batches).toHaveLength(0)})
 it('retries return the original record even after another batch exists',()=>{const s=create(create(),'r2','b2');const retry=applyCommand(s,{kind:'batch',data},'r',now,'ignored');expect(retry.result).toBe('b');expect(retry.workspace.batches).toHaveLength(2)})
 it('rejects a reused request with different content',()=>expect(()=>applyCommand(create(),{kind:'batch',data:{...data,quantity:11}},'r',now,'x')).toThrow('conflicts'))
 it('keeps unknown quantities unknown and has no guessed deadline',()=>{const b=create(seed,'r','b',{...data,quantity:null}).batches[0];expect(b.remaining_quantity).toBeNull();expect(b.status).toBe('needs-information');expect(b.advisory_deadline).toBeNull()})
 it('rejects future preparation and fractional quantities',()=>{expect(()=>create(seed,'r','b',{...data,prepared_at:'2026-10-02T11:00:00Z'})).toThrow();expect(()=>create(seed,'r','b',{...data,quantity:1.5})).toThrow()})
 it('does not change Batch 2 when Batch 1 sells out',()=>{const s=create(create(),'r2','b2');const result=applyCommand(s,{kind:'action',data:{batch_id:'b',action:'sold-out'}},'sale',now,'x').workspace;expect(result.batches[0].remaining_quantity).toBe(0);expect(result.batches[1]).toEqual(s.batches[1]);expect(result.events.at(-1)?.kind).toBe('sold-out')})
 it('rejects overselling atomically and prevents consuming closed stock',()=>{const s=create();expect(()=>applyCommand(s,{kind:'action',data:{batch_id:'b',action:'consume',quantity:11}},'sale',now,'x')).toThrow();expect(s.batches[0].remaining_quantity).toBe(10);const closed=applyCommand(s,{kind:'action',data:{batch_id:'b',action:'withdrawn'}},'w',now,'x').workspace;expect(()=>applyCommand(closed,{kind:'action',data:{batch_id:'b',action:'consume',quantity:1}},'sale',now,'x')).toThrow()})
 it('allows discard after withdrawal but never restores discarded stock',()=>{const s=applyCommand(create(),{kind:'action',data:{batch_id:'b',action:'withdrawn'}},'w',now,'x').workspace;const discarded=applyCommand(s,{kind:'action',data:{batch_id:'b',action:'discarded'}},'d',now,'x').workspace;expect(discarded.batches[0].status).toBe('discarded');expect(()=>applyCommand(discarded,{kind:'action',data:{batch_id:'b',action:'available'}},'a',now,'x')).toThrow()})
 it('only shortens corrected deadlines and preserves original timestamps',()=>{const s=create();s.batches[0].advisory_deadline='2026-10-01T13:00:00Z';const result=applyCommand(s,{kind:'action',data:{batch_id:'b',action:'correct',prepared_at:'2026-10-01T10:30:00Z'}},'c',now,'x').workspace.batches[0];expect(result.prepared_at).toBe(data.prepared_at);expect(result.advisory_deadline).toBe('2026-10-01T12:30:00.000Z');expect(()=>applyCommand(s,{kind:'action',data:{batch_id:'b',action:'correct',prepared_at:'2026-10-01T11:30:00Z'}},'c',now,'x')).toThrow()})
 it('merges with earliest corrected time/deadline and closes sources',()=>{const s=create(create(),'r2','b2',{...data,prepared_at:'2026-10-01T11:30:00Z'});s.batches[0].advisory_deadline='2026-10-01T13:00:00Z';s.batches[1].advisory_deadline='2026-10-01T14:00:00Z';const result=applyCommand(s,{kind:'merge',data:{source_ids:['b2','b']}},'merge',now,'merged').workspace;expect(result.batches.slice(0,2).map(b=>b.status)).toEqual(['merged','merged']);const merged=result.batches[2];expect(merged.batch_number).toBe(3);expect(merged.advisory_deadline).toBe(s.batches[0].advisory_deadline);expect(merged.prepared_at).toBe(s.batches[0].prepared_at);expect(merged.remaining_quantity).toBe(20);expect(merged.status).toBe('needs-information');expect(merged.photo).toBeNull()})
 it('merging unknown stock/deadline cannot invent known stock or a window',()=>{const s=create(create(),'r2','b2',{...data,quantity:null});s.batches[0].advisory_deadline='2026-10-01T13:00:00Z';const b=applyCommand(s,{kind:'merge',data:{source_ids:['b','b2']}},'m',now,'x').workspace.batches[2];expect(b.remaining_quantity).toBeNull();expect(b.advisory_deadline).toBeNull()})
 it('rejects duplicate-only merge selections and mixed foods',()=>{const s=create(create(),'r2','b2');expect(()=>applyCommand(s,{kind:'merge',data:{source_ids:['b','b']}},'m',now,'x')).toThrow();s.batches[1].food_item_id='other';expect(()=>applyCommand(s,{kind:'merge',data:{source_ids:['b','b2']}},'m',now,'x')).toThrow()})
 it.each([['5',500],['5.2',520],['0.01',1]])('converts %s to integer sen',(value,expected)=>expect(money(value as string)).toBe(expected))
 it.each(['5.001','-1','NaN','1e3'])('rejects invalid RM input %s',value=>expect(()=>money(value)).toThrow())
})
